"""Prepare a reference-only review board; never registers or submits video."""
from pathlib import Path
import json,hashlib,os,re,html
from PIL import Image
ROOT=Path.cwd();V=Path(__file__).resolve().parent;REF=ROOT/'referces/shizhen/macro-opening-20261027'
source_identity=ROOT/'referces/shizhen/character-packs-20261027/dong-wenhui/identity/identity-v1.png'
specs=[
('A0','下楼起态',REF/'L01-X.png','reuse','背对摄影机朝下方关门行进；正常平台的灭火器与管道同框'),
('A1','继续下降',REF/'action-sequences-04/A1-descent.png','new','同机位、更低且更远；双脚分处下行台阶，不回身'),
('A2','到达下平台',REF/'action-sequences-04/A2-arrival.png','new','双脚已落在关门前平地；双手空着，尚未碰把手'),
('B0','伸手之前',REF/'action-sequences-04/B0-before-contact.png','new','换至门外近处机位，门仍关闭、右手仍空着'),
('B1','接触把手',REF/'door-push-repair-03/L02-push-closed.png','reuse','右手接触把手；门仍关闭，人物留在门槛外'),
('B2','向内半开',REF/'action-sequences-04/B1-contact-push.png','new','右手仍接触把手；门自由边向门内退，线索开始显露'),
('B3','打开并扶住',REF/'door-push-repair-03/L03-push-open.png','reuse','门向内开得更大，右手保持扶门；灭火器、旧卡箍印可见')]
assets=[]
for id,title,p,origin,purpose in specs:
 with Image.open(p) as im:
  im.verify()
 with Image.open(p) as im:w,h=im.size;mode=im.mode
 assets.append({'review_id':id,'title':title,'path':p.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'size_bytes':p.stat().st_size,'width':w,'height':h,'mode':mode,'origin':origin,'purpose':purpose,'future_group':'descent_arrival' if id.startswith('A') else 'contact_push_reveal','current_video_binding':False,'human_acceptance':'NOT_EVALUATED','dynamic_acceptance':'NOT_EVALUATED'})
prompts=[]
for p in sorted((REF/'action-sequences-04').glob('*.prompt.zh.txt')):
 body=p.read_text();assert not re.search('[A-Za-z]',body);prompts.append({'path':p.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'pure_chinese':True})
manifest={'scope':'Static reference candidates and planned roles; not Registry, timeline, upload or video binding','identity_parent':{'path':source_identity.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(source_identity.read_bytes()).hexdigest()},'images':assets,'prompts':prompts,'new_builtin_image_calls':4,'macro_builtin_image_calls_before':22,'macro_builtin_image_calls_after':26,'new_video_calls':0,'macro_video_calls_unchanged':5,'old_media_findings_retained':True,'proposed_groups':[{'id':'descent_arrival','sequence':['A0','A1','A2'],'scope':'normal clue establishment and full visible-flight downward arrival; no door opening'},{'id':'contact_push_reveal','sequence':['B0','B1','B2','B3'],'scope':'reach/contact, one inward push and held-door reaction; no stairs'}],'handoff':{'from':'A2','to':'B0','type':'same_place_view_change','preserve':['closed door','free right hand','feet on lower landing before threshold'],'review_note':'Different camera distances explain subject scale; source/cut continuity and reach timing require actual generated media'},'future_input_caution':'These are intended group references, not current submitted images. Any video request must choose supported mode and explicitly bind all selected control references; two-slot first/last mode cannot silently claim to contain intermediate states. Image order alone does not establish motion timing. No fixed5s cut prescribed.','dynamic_status':'NOT_EVALUATED','human_status':'NOT_EVALUATED','actual_charges':'NOT_CONFIRMED'}
(V/'reference-input-plan.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
def card(a):
 rel=Path(os.path.relpath(ROOT/a['path'],V)).as_posix();return f'<article><a href="{html.escape(rel)}" target="_blank"><img src="{html.escape(rel)}" alt="{html.escape(a["title"])}"></a><h3>{a["review_id"]} · {a["title"]}</h3><p>{a["purpose"]}</p><a class="original" href="{html.escape(rel)}" target="_blank">打开干净单图 ↗</a><small>{"新补" if a["origin"]=="new" else "复用"} · {a["width"]} × {a["height"]}</small></article>'
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>失帧 · 楼梯动作参考04</title><style>*{box-sizing:border-box}body{margin:0;background:#111619;color:#e9edeb;font:16px/1.6 system-ui,sans-serif}main{max-width:1540px;margin:auto;padding:36px 28px 60px}.eyebrow{color:#a8c6ba;letter-spacing:.12em}h1{font-size:36px;margin:8px 0}h2{font-size:25px;margin:38px 0 8px}.intro,.status{max-width:1000px;color:#b9c7c4}.status{padding:14px 18px;background:#26302c;border-left:3px solid #adca9d}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.doors{grid-template-columns:repeat(4,minmax(0,1fr))}article{border:1px solid #37413f;background:#1a2225;padding:10px 10px 16px;border-radius:8px}article img{width:100%;height:auto;display:block}h3{font-size:18px;margin:14px 4px 6px}article p{color:#bdc7c4;margin:0 4px 14px;font-size:14px;min-height:48px}a{color:#c5e2d7}.original{margin:4px}small{display:block;color:#99aaa5;margin:10px 4px 0}.handoff{padding:18px;border:1px solid #4c5d56;margin:28px 0;color:#cad5d1}footer{margin-top:30px;color:#96a8a2}@media(max-width:1050px){.doors{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){main{padding:24px 14px}.grid,.doors{grid-template-columns:1fr}h1{font-size:27px}article p{min-height:0}}</style><main><div class="eyebrow">《失帧》 · MC03—MC05 · 动作参考04</div><h1>把下楼与推门分别交代清楚</h1><p class="intro">点击图片可查看干净原图。所有标注均在图片之外；新补4张、复用3张，人物身份与服装沿用现有资料。</p><p class="status">静态候选，待审看。尚未用这套图生成视频；人物运动、手部持续接触、声音和剪辑仍须看实际成片验证。</p><h2>一 · 从楼梯下行，到关门前</h2><p>固定同一楼梯观察机位，让位置逐步降低；门后线索尚未出现。</p><section class="grid">'''+''.join(card(a) for a in assets[:3])+'''</section><div class="handoff"><strong>两组的接点：</strong>A2与B0均为到达门外、双手空着、门关闭。换机位后再完成伸手握把，避免直接跳成已经握门。实际剪点按动作确定，不预设五秒切镜。</div><h2>二 · 先接触，再向内推开并扶住</h2><p>保持同一门外机位，比较右手、把手、门自由边与门槛位置。</p><section class="grid doors">'''+''.join(card(a) for a in assets[3:])+'''</section><footer>本板只审外观、空间和动作状态，不能据此签视频通过。<br><a href="reference-input-plan.json">来源、哈希及拟用途记录</a> · <a href="../index-stairs-v2.html">保留的失败视频修订02</a></footer></main></html>'''
(V/'index.html').write_text(page)
print(json.dumps({'images':len(assets),'new_images':4,'all_pngs_verified':True,'all_prompts_chinese':True,'board':str(V/'index.html'),'new_video_calls':0},ensure_ascii=False))
